rerenderStream: AnyStream,\n  opts: import('./stream-ops.web').ContinueStaticPrerenderOptions\n): Promise<AnyStream> {\n  const webResult = await webContinueStaticPrerender(\n    nodeReadableToWebReadableStream(prerenderStream),\n    {\n      ...opts,\n      inlinedDataStream: nodeReadableToWebReadableStream(\n        opts.inlinedDataStream\n      ),\n    }\n  )\n  return webToReadable(webResult)\n}\n\nexport async function continueDynamicPrerender(\n  prerenderStream: AnyStream,\n  opts: {\n    getServerInsertedHTML: () => Promise<string>\n    getServerInsertedMetadata: () => Promise<string>\n    deploymentId: string | undefined\n  }\n): Promise<AnyStream> {\n  const webResult = await webContinueDynamicPrerender(\n    nodeReadableToWebReadableStream(prerenderStream),\n    opts\n  )\n  return webToReadable(webResult)\n}\n\nexport async function continueStaticFallbackPrerender(\n  prerenderStream: AnyStream,\n  opts: import('./stream-ops.web').ContinueStaticPrerenderOptions\n): Promise<AnyStream> {\n  const webResult = await webContinueStaticFallbackPrerender(\n    nodeReadableToWebReadableStream(prerenderStream),\n    {\n      ...opts,\n      inlinedDataStream: nodeReadableToWebReadableStream(\n        opts.inlinedDataStream\n      ),\n    }\n  )\n  return webToReadable(webResult)\n}\n\nexport async function continueDynamicHTMLResumeNode(\n  renderStream: AnyStream,\n  {\n    delayDataUntilFirstHtmlChunk,\n    inlinedDataStream,\n    getServerInsertedHTML,\n    getServerInsertedMetadata,\n    deploymentId,\n  }: import('./stream-ops.web').ContinueDynamicHTMLResumeOptions\n): Promise<AnyStream> {\n  await waitAtLeastOneReactRenderTask()\n\n  const buffered = createNodeBufferedTransformStream()\n  webToReadable(renderStream).pipe(buffered)\n\n  let source: Readable = buffered\n\n  if (deploymentId) {\n    const dplId = createHtmlDataDplIdTransform(deploymentId)\n    source.pipe(dplId)\n    source = dplId\n  }\n\n  const headInsertion = createHeadInsertionTransform(getServerInsertedHTML)\n  source.pipe(headInsertion)\n  source = headInsertion\n\n  const metadata = createMetadataTransform(getServerInsertedMetadata)\n  source.pipe(metadata)\n  source = metadata\n\n  const flightInjection = createFlightDataInjectionTransform(\n    webToReadable(inlinedDataStream),\n    delayDataUntilFirstHtmlChunk\n  )\n  source.pipe(flightInjection)\n  source = flightInjection\n\n  const moveSuffix = createMoveSuffixTransform()\n  source.pipe(moveSuffix)\n  source = moveSuffix\n\n  return source\n}\n\nexport async function continueDynamicHTMLResumeWeb(\n  renderStream: AnyStream,\n  opts: import('./stream-ops.web').ContinueDynamicHTMLResumeOptions\n): Promise<AnyStream> {\n  const webResult = await webContinueDynamicHTMLResume(\n    nodeReadableToWebReadableStream(renderStream),\n    {\n      ...opts,\n      inlinedDataStream: nodeReadableToWebReadableStream(\n        opts.inlinedDataStream\n      ),\n    }\n  )\n  return webToReadable(webResult)\n}\n\n// ---------------------------------------------------------------------------\n// Utility functions (Node-native)\n// ---------------------------------------------------------------------------\n\nexport function chainStreams(...streams: AnyStream[]): AnyStream {\n  if (streams.length === 0) {\n    const pt = new PassThrough()\n    pt.end()\n    return pt\n  }\n\n  if (streams.length === 1) {\n    return streams[0]\n  }\n\n  const out = new PassThrough()\n  let i = 0\n\n  function pipeNext() {\n    if (i >= streams.length) {\n      out.end()\n      return\n    }\n    const current = webToReadable(streams[i++])\n    current.pipe(out, { end: false })\n    current.on('end', pipeNext)\n    current.on('error', (err) => out.destroy(err))\n  }\n\n  pipeNext()\n  return out\n}\n\nexport async function streamToBuffer(stream: AnyStream): Promise<Buffer> {\n  return webStreamToBuffer(nodeReadableToWebReadableStream(stream))\n}\n\nexport async function streamToString(stream: AnyStream): Promise<string> {\n  return webStreamToString(nodeReadableToWebReadableStream(stream))\n}\n\nexport function createWebInlinedDataStream(\n  source: AnyStream,\n  nonce: string | undefined,\n  formState: unknown | null\n): AnyStream {\n  const webSource = nodeReadableToWebReadableStream(source)\n  const webResult = createInlinedDataReadableStream(webSource, nonce, formState)\n  return webToReadable(webResult)\n}\n\nexport function createNodeInlinedDataStream(\n  source: AnyStream,\n  nonce: string | undefined,\n  formState: unknown | null\n): AnyStream {\n  const startScriptTag = nonce\n    ? `<script nonce=\"${htmlEscapeAttributeString(nonce)}\">`\n    : '<script>'\n\n  const dataStream = webToReadable(source)\n  const pt = new PassThrough()\n\n  // Write initial bootstrap instructions\n  let scriptContents = `(self.__next_f=self.__next_f||[]).push(${htmlEscapeJsonString(\n    JSON.stringify([INLINE_FLIGHT_PAYLOAD_BOOTSTRAP])\n  )})`\n  if (formState != null) {\n    scriptContents += `;self.__next_f.push(${htmlEscapeJsonString(\n      JSON.stringify([INLINE_FLIGHT_PAYLOAD_FORM_STATE, formState])\n    )})`\n  }\n  pt.push(Buffer.from(`${startScriptTag}${scriptContents}</script>`))\n\n  // Pull from the flight data stream and wrap each chunk in a <script> tag\n  pullFlightData(dataStream, pt, startScriptTag)\n\n  return pt\n}\n\nconst INLINE_FLIGHT_PAYLOAD_BOOTSTRAP = 0\nconst INLINE_FLIGHT_PAYLOAD_DATA = 1\nconst INLINE_FLIGHT_PAYLOAD_FORM_STATE = 2\nconst INLINE_FLIGHT_PAYLOAD_BINARY = 3\n\nasync function pullFlightData(\n  dataStream: Readable,\n  output: PassThrough,\n  startScriptTag: string\n): Promise<void> {\n  function waitForReadableOrEnd(): Promise<void> {\n    if (dataStream.readableLength > 0 || dataStream.readableEnded) {\n      return Promise.resolve()\n    }\n    return new Promise<void>((resolve, reject) => {\n      function cleanup() {\n        dataStream.removeListener('readable', onDone)\n        dataStream.removeListener('end', onDone)\n        dataStream.removeListener('error', onError)\n      }\n      function onDone() {\n        cleanup()\n        resolve()\n      }\n      function onError(err: Error) {\n        cleanup()\n        reject(err)\n      }\n      dataStream.on('readable', onDone)\n      dataStream.on('end', onDone)\n      dataStream.on('error', onError)\n    })\n  }\n\n  try {\n    while (true) {\n      const chunk: Buffer | null = dataStream.read()\n      if (chunk !== null) {\n        let htmlInlinedData: string\n        if (isUtf8(chunk)) {\n          const decodedString = chunk.toString('utf-8')\n          htmlInlinedData = htmlEscapeJsonString(\n            JSON.stringify([INLINE_FLIGHT_PAYLOAD_DATA, decodedString])\n          )\n        } else {\n          const base64 = Buffer.from(\n            chunk.buffer,\n            chunk.byteOffset,\n            chunk.byteLength\n          ).toString('base64')\n          htmlInlinedData = htmlEscapeJsonString(\n            JSON.stringify([INLINE_FLIGHT_PAYLOAD_BINARY, base64])\n          )\n        }\n        output.push(\n          Buffer.from(\n            `${startScriptTag}self.__next_f.push(${htmlInlinedData})</script>`\n          )\n        )\n        continue\n      }\n\n      if (dataStream.readableEnded) {\n        output.end()\n        return\n      }\n\n      await waitForReadableOrEnd()\n    }\n  } catch (err) {\n    output.destroy(err as Error)\n  }\n}\n\nexport function createPendingStream(): AnyStream {\n  return new PassThrough()\n}\n\nexport function createDocumentClosingStream(): AnyStream {\n  const webStream = webCreateDocumentClosingStream()\n  return webToReadable(webStream)\n}\n\nexport function createOnHeadersCallback(\n  appendHeader: (key: string, value: string) => void\n): NonNullable<PrerenderOptions['onHeaders']> {\n  return (headers: Headers) => {\n    headers.forEach((value, key) => {\n      appendHeader(key, value)\n    })\n  }\n}\n\nexport function pipeRuntimePrefetchTransform(\n  stream: AnyStream,\n  sentinel: number,\n  isPartial: boolean,\n  staleTime: number\n): AnyStream {\n  const webStream = nodeReadableToWebReadableStream(stream)\n  const transformed = webStream.pipeThrough(\n    createRuntimePrefetchTransformStream(sentinel, isPartial, staleTime)\n  )\n  return webToReadable(transformed)\n}\n\n// ---------------------------------------------------------------------------\n// Re-exports (no stream involvement, identical to web)\n// ---------------------------------------------------------------------------\n\nexport async function processPrelude(unprocessedPrelude: AnyStream) {\n  const [prelude, peek] =\n    nodeReadableToWebReadableStream(unprocessedPrelude).tee()\n\n  const reader = peek.getReader()\n  const firstResult = await reader.read()\n  reader.cancel()\n\n  return {\n    prelude: webToReadable(prelude) as AnyStream,\n    preludeIsEmpty: firstResult.done === true,\n  }\n}\n\nexport function getServerPrerender(ComponentMod: {\n  prerender: (...args: any[]) => Promise<any>\n}): (...args: any[]) => any {\n  return ComponentMod.prerender\n}\n\nexport const getClientPrerender: typeof import('react-dom/static').prerender =\n  prerender\n\n// Node counterpart of the web `teeStream`. Like the web version it assumes the\n// stream type matching its build — here a Node `Readable` — and fans out\n// through `ReplayableNodeStream`. Need three or more consumers from one source?\n// Use `ReplayableNodeStream` directly (N `createReplayStream()` calls) to avoid\n// nesting tees.\nexport function teeStream(stream: AnyStream): [AnyStream, AnyStream] {\n  const replayable = new ReplayableNodeStream(stream as Readable)\n  return [replayable.createReplayStream(), replayable.createReplayStream()]\n}\n","import type { BinaryStreamOf } from './app-render'\nimport type { Readable } from 'node:stream'\n\nimport {\n  htmlEscapeAttributeString,\n  htmlEscapeJsonString,\n} from '../../shared/lib/htmlescape'\nimport { workUnitAsyncStorage } from './work-unit-async-storage.external'\nimport { InvariantError } from '../../shared/lib/invariant-error'\nimport { getClientReferenceManifest } from './manifests-singleton'\n\nconst isEdgeRuntime = process.env.NEXT_RUNTIME === 'edge'\n\nconst INLINE_FLIGHT_PAYLOAD_BOOTSTRAP = 0\nconst INLINE_FLIGHT_PAYLOAD_DATA = 1\nconst INLINE_FLIGHT_PAYLOAD_FORM_STATE = 2\nconst INLINE_FLIGHT_PAYLOAD_BINARY = 3\n\nconst flightResponses = new WeakMap<\n  Readable | BinaryStreamOf<any>,\n  Promise<any>\n>()\nconst encoder = new TextEncoder()\n\nconst findSourceMapURL =\n  process.env.NODE_ENV !== 'production'\n    ? (require('../lib/source-maps') as typeof import('../lib/source-maps'))\n        .findSourceMapURLDEV\n    : undefined\n\n/**\n * Render Flight stream.\n * This is only used for renderToHTML, the Flight response does not need additional wrappers.\n */\nexport function getFlightStream<T>(\n  flightStream: Readable | BinaryStreamOf<T>,\n  debugStream: Readable | ReadableStream<Uint8Array> | undefined,\n  debugEndTime: number | undefined,\n  nonce: string | undefined\n): Promise<T> {\n  const response = flightResponses.get(flightStream)\n\n  if (response) {\n    return response\n  }\n\n  const { moduleLoading, edgeSSRModuleMapping, ssrModuleMapping } =\n    getClientReferenceManifest()\n\n  let newResponse: Promise<T>\n  if (flightStream instanceof ReadableStream) {\n    // The types of flightStream and debugStream should match.\n    if (debugStream && !(debugStream instanceof ReadableStream)) {\n      throw new InvariantError('Expected debug stream to be a ReadableStream')\n    }\n\n    // react-server-dom-webpack/client.edge must not be hoisted for require cache clearing to work correctly\n    const { createFromReadableStream } =\n      // eslint-disable-next-line import/no-extraneous-dependencies\n      require('react-server-dom-webpack/client') as typeof import('react-server-dom-webpack/client')\n\n    newResponse = createFromReadableStream<T>(flightStream, {\n      findSourceMapURL,\n      serverConsumerManifest: {\n        moduleLoading,\n        moduleMap: isEdgeRuntime ? edgeSSRModuleMapping : ssrModuleMapping,\n        serverModuleMap: null,\n      },\n      nonce,\n      debugChannel: debugStream ? { readable: debugStream } : undefined,\n      endTime: debugEndTime,\n    })\n  } else {\n    if (process.env.NEXT_RUNTIME === 'edge') {\n      throw new InvariantError(\n        'getFlightStream should always receive a ReadableStream when using the edge runtime'\n      )\n    } else {\n      const { Readable } =\n        require('node:stream') as typeof import('node:stream')\n\n      // Convert debug stream to Readable if it's a ReadableStream.\n      // When __NEXT_USE_NODE_STREAMS is enabled, the debug channel produces\n      // Node Readables natively. Otherwise, it produces web ReadableStreams.\n      let nodeDebugStream: Readable | undefined\n      if (debugStream) {\n        if (debugStream instanceof Readable) {\n          nodeDebugStream = debugStream\n        } else {\n          type WebReadableStream = import('stream/web').ReadableStream\n          nodeDebugStream = Readable.fromWeb(debugStream as WebReadableStream)\n        }\n      }\n\n      // react-server-dom-webpack/client.edge must not be hoisted for require cache clearing to work correctly\n      const { createFromNodeStream } =\n        // eslint-disable-next-line import/no-extraneous-dependencies\n        require('react-server-dom-webpack/client') as typeof import('react-server-dom-webpack/client')\n\n      newResponse = createFromNodeStream<T>(\n        flightStream,\n        {\n          moduleLoading,\n          moduleMap: isEdgeRuntime ? edgeSSRModuleMapping : ssrModuleMapping,\n          serverModuleMap: null,\n        },\n        {\n          findSourceMapURL,\n          nonce,\n          debugChannel: nodeDebugStream,\n          endTime: debugEndTime,\n        }\n      )\n    }\n  }\n\n  // Edge pages are never prerendered so they necessarily cannot have a workUnitStore type\n  // that requires the nextTick behavior. This is why it is safe to access a node only API here\n  if (process.env.NEXT_RUNTIME !== 'edge') {\n    const workUnitStore = workUnitAsyncStorage.getStore()\n\n    if (!workUnitStore) {\n      throw new InvariantError('Expected workUnitAsyncStorage to have a store.')\n    }\n\n    switch (workUnitStore.type) {\n      case 'prerender-client':\n      case 'validation-client':\n        const responseOnNextTick = new Promise<T>((resolve) => {\n          process.nextTick(() => {\n            resolve(newResponse)\n          })\n        })\n        flightResponses.set(flightStream, responseOnNextTick)\n        return responseOnNextTick\n      case 'prerender':\n      case 'prerender-runtime':\n      case 'prerender-ppr':\n      case 'prerender-legacy':\n      case 'request':\n      case 'cache':\n      case 'private-cache':\n      case 'unstable-cache':\n      case 'generate-static-params':\n        break\n      default:\n        workUnitStore satisfies never\n    }\n  }\n\n  flightResponses.set(flightStream, newResponse)\n\n  return newResponse\n}\n\n/**\n * Creates a ReadableStream provides inline script tag chunks for writing hydration\n * data to the client outside the React render itself.\n *\n * @param flightStream The RSC render stream\n * @param nonce optionally a nonce used during this particular render\n * @param formState optionally the formState used with this particular render\n * @returns a ReadableStream without the complete property. This signifies a lazy ReadableStream\n */\nexport function createInlinedDataReadableStream(\n  flightStream: ReadableStream<Uint8Array>,\n  nonce: string | undefined,\n  formState: unknown | null\n): ReadableStream<Uint8Array> {\n  const startScriptTag = nonce\n    ? `<script nonce=\"${htmlEscapeAttributeString(nonce)}\">`\n    : '<script>'\n\n  const flightReader = flightStream.getReader()\n  const decoder = new TextDecoder('utf-8', { fatal: true })\n\n  const readable = new ReadableStream({\n    type: 'bytes',\n    start(controller) {\n      try {\n        writeInitialInstructions(controller, startScriptTag, formState)\n      } catch (error) {\n        // during encoding or enqueueing forward the error downstream\n        controller.error(error)\n      }\n    },\n    async pull(controller) {\n      try {\n        const { done, value } = await flightReader.read()\n\n        if (value) {\n          try {\n            const decodedString = decoder.decode(value, { stream: !done })\n\n            // The chunk cannot be decoded as valid UTF-8 string as it might\n            // have arbitrary binary data.\n            writeFlightDataInstruction(\n              controller,\n              startScriptTag,\n              decodedString\n            )\n          } catch {\n            // The chunk cannot be decoded as valid UTF-8 string.\n            writeFlightDataInstruction(controller, startScriptTag, value)\n          }\n        }\n\n        if (done) {\n          controller.close()\n        }\n      } catch (error) {\n        // There was a problem in the upstream reader or during decoding or enqueuing\n        // forward the error downstream\n        controller.error(error)\n      }\n    },\n  })\n\n  return readable\n}\n\nfunction writeInitialInstructions(\n  controller: ReadableStreamDefaultController,\n  scriptStart: string,\n  formState: unknown | null\n) {\n  let scriptContents = `(self.__next_f=self.__next_f||[]).push(${htmlEscapeJsonString(\n    JSON.stringify([INLINE_FLIGHT_PAYLOAD_BOOTSTRAP])\n  )})`\n\n  if (formState != null) {\n    scriptContents += `;self.__next_f.push(${htmlEscapeJsonString(\n      JSON.stringify([INLINE_FLIGHT_PAYLOAD_FORM_STATE, formState])\n    )})`\n  }\n\n  controller.enqueue(encoder.encode(`${scriptStart}${scriptContents}</script>`))\n}\n\nfunction writeFlightDataInstruction(\n  controller: ReadableStreamDefaultController,\n  scriptStart: string,\n  chunk: string | Uint8Array\n) {\n  let htmlInlinedData: string\n\n  if (typeof chunk === 'string') {\n    htmlInlinedData = htmlEscapeJsonString(\n      JSON.stringify([INLINE_FLIGHT_PAYLOAD_DATA, chunk])\n    )\n  } else {\n    // The chunk cannot be embedded as a UTF-8 string in the script tag.\n    // Instead let's inline it in base64.\n    // Credits to Devon Govett (devongovett) for the technique.\n    // https://github.com/devongovett/rsc-html-stream\n    const base64 =\n      typeof Buffer !== 'undefined'\n        ? Buffer.from(\n            chunk.buffer,\n            chunk.byteOffset,\n            chunk.byteLength\n          ).toString('base64')\n        : btoa(String.fromCodePoint(...chunk))\n    htmlInlinedData = htmlEscapeJsonString(\n      JSON.stringify([INLINE_FLIGHT_PAYLOAD_BINARY, base64])\n    )\n  }\n\n  controller.enqueue(\n    encoder.encode(\n      `${scriptStart}self.__next_f.push(${htmlInlinedData})</script>`\n    )\n  )\n}\n","import crypto from 'crypto'\n\n// Background:\n// https://security.stackexchange.com/questions/184305/why-would-i-ever-use-aes-256-cbc-if-aes-256-gcm-is-more-secure\n\nconst CIPHER_ALGORITHM = `aes-256-gcm`,\n  CIPHER_KEY_LENGTH = 32, // https://stackoverflow.com/a/28307668/4397028\n  CIPHER_IV_LENGTH = 16, // https://stackoverflow.com/a/28307668/4397028\n  CIPHER_TAG_LENGTH = 16,\n  CIPHER_SALT_LENGTH = 64\n\nconst PBKDF2_ITERATIONS = 100_000 // https://support.1password.com/pbkdf2/\n\nexport function encryptWithSecret(secret: Buffer, data: string): string {\n  const iv = crypto.randomBytes(CIPHER_IV_LENGTH)\n  const salt = crypto.randomBytes(CIPHER_SALT_LENGTH)\n\n  // https://nodejs.org/api/crypto.html#crypto_crypto_pbkdf2sync_password_salt_iterations_keylen_digest\n  const key = crypto.pbkdf2Sync(\n    secret,\n    salt,\n    PBKDF2_ITERATIONS,\n    CIPHER_KEY_LENGTH,\n    `sha512`\n  )\n\n  const cipher = crypto.createCipheriv(CIPHER_ALGORITHM, key, iv)\n  const encrypted = Buffer.concat([cipher.update(data, `utf8`), cipher.final()])\n\n  // https://nodejs.org/api/crypto.html#crypto_cipher_getauthtag\n  const tag = cipher.getAuthTag()\n\n  return Buffer.concat([\n    // Data as required by:\n    // Salt for Key: https://nodejs.org/api/crypto.html#crypto_crypto_pbkdf2sync_password_salt_iterations_keylen_digest\n    // IV: https://nodejs.org/api/crypto.html#crypto_class_decipher\n    // Tag: https://nodejs.org/api/crypto.html#crypto_decipher_setauthtag_buffer\n    salt,\n    iv,\n    tag,\n    encrypted,\n  ]).toString(`hex`)\n}\n\nexport function decryptWithSecret(\n  secret: Buffer,\n  encryptedData: string\n): string {\n  const buffer = Buffer.from(encryptedData, `hex`)\n\n  const salt = buffer.slice(0, CIPHER_SALT_LENGTH)\n  const iv = buffer.slice(\n    CIPHER_SALT_LENGTH,\n    CIPHER_SALT_LENGTH + CIPHER_IV_LENGTH\n  )\n  const tag = buffer.slice(\n    CIPHER_SALT_LENGTH + CIPHER_IV_LENGTH,\n    CIPHER_SALT_LENGTH + CIPHER_IV_LENGTH + CIPHER_TAG_LENGTH\n  )\n  const encrypted = buffer.slice(\n    CIPHER_SALT_LENGTH + CIPHER_IV_LENGTH + CIPHER_TAG_LENGTH\n  )\n\n  // https://nodejs.org/api/crypto.html#crypto_crypto_pbkdf2sync_password_salt_iterations_keylen_digest\n  const key = crypto.pbkdf2Sync(\n    secret,\n    salt,\n    PBKDF2_ITERATIONS,\n    CIPHER_KEY_LENGTH,\n    `sha512`\n  )\n\n  const decipher = crypto.createDecipheriv(CIPHER_ALGORITHM, key, iv)\n  decipher.setAuthTag(tag)\n\n  return decipher.update(encrypted) + decipher.final(`utf8`)\n}\n","/**\n * This is the default \"use cache\" handler it defaults to an in-memory store.\n * In-memory caches are fragile and should not use stale-while-revalidate\n * semantics on the caches because it's not worth warming up an entry that's\n * likely going to get evicted before we get to use it anyway. However, we also\n * don't want to reuse a stale entry for too long so stale entries should be\n * considered expired/missing in such cache handlers.\n *\n * The dev server (`next dev`) is the exception: to keep reloads fast it serves\n * stale entries until they expire, relying on the wrapper's\n * stale-while-revalidate path to warm a fresh entry in the background. See\n * `get` for where this branches.\n */\n\nimport { LRUCache } from '../lru-cache'\nimport type { CacheEntry, CacheHandler } from './types'\nimport {\n  areTagsExpired,\n  areTagsStale,\n  tagsManifest,\n  type TagManifestEntry,\n} from '../incremental-cache/tags-manifest.external'\nimport { MIN_PRERENDERABLE_EXPIRE } from '../../use-cache/constants'\n\ntype PrivateCacheEntry = {\n  entry: CacheEntry\n\n  // For the default cache we store errored cache\n  // entries and allow them to be used up to 3 times\n  // after that we want to dispose it and try for fresh\n\n  // If an entry is errored we return no entry\n  // three times so that we retry hitting origin (MISS)\n  // and then if it still fails to set after the third we\n  // return the errored content and use expiration of\n  // Math.min(30, entry.expiration)\n  isErrored: boolean\n  errorRetryCount: number\n\n  // compute size on set since we need to read size\n  // of the ReadableStream for LRU evicting\n  size: number\n}\n\nexport function createDefaultCacheHandler(maxSize: number): CacheHandler {\n  // If the max size is 0, return a cache handler that doesn't cache anything,\n  // this avoids an unnecessary LRUCache instance and potential memory\n  // allocation.\n  if (maxSize === 0) {\n    return {\n      get: () => Promise.resolve(undefined),\n      set: () => Promise.resolve(),\n      refreshTags: () => Promise.resolve(),\n      getExpiration: () => Promise.resolve(0),\n      updateTags: () => Promise.resolve(),\n    }\n  }\n\n  const memoryCache = new LRUCache<PrivateCacheEntry>(\n    maxSize,\n    (entry, cacheKey) => entry.size + cacheKey.length\n  )\n  const pendingSets = new Map<string, Promise<void>>()\n\n  const debug = process.env.NEXT_PRIVATE_DEBUG_CACHE\n    ? console.debug.bind(console, 'DefaultCacheHandler:')\n    : undefined\n\n  return {\n    async get(cacheKey) {\n      const pendingPromise = pendingSets.get(cacheKey)\n\n      if (pendingPromise) {\n        debug?.('get', cacheKey, 'pending')\n        await pendingPromise\n      }\n\n      const privateEntry = memoryCache.get(cacheKey)\n\n      if (!privateEntry) {\n        debug?.('get', cacheKey, 'not found')\n        return undefined\n      }\n\n      const entry = privateEntry.entry\n\n      // A negative `expire` is an eviction sentinel: the tiered cache handler\n      // (dev-only) marks a front entry for deletion by overwriting it with a\n      // negative `expire`, since the cache-handler interface has no per-key\n      // delete. Treat it as missing here, independently of the minimum\n      // retention below (which would otherwise keep it alive). This is distinct\n      // from `revalidate = -1` below, which keeps serving the entry but forces\n      // a revalidation.\n      if (entry.expire < 0) {\n        debug?.('get', cacheKey, 'evicted')\n        return undefined\n      }\n\n      // The dev server serves stale entries until they expire (see the file\n      // overview); production drops them once past the revalidate time. In dev,\n      // an entry is retained for at least `MIN_PRERENDERABLE_EXPIRE` so that\n      // entries with a short `expire` (for example a `cacheLife({ expire: 0 })`\n      // client-only cache) still linger long enough that a reload hits the\n      // cache. That minimum is the same threshold below which the \"use cache\"\n      // wrapper treats an entry as dynamic, so it only extends the retention of\n      // entries that are dynamic anyway. It affects retention only; the\n      // returned entry keeps its real `expire`, so staging decisions are\n      // unchanged.\n      const maxAgeSeconds = process.env.__NEXT_DEV_SERVER\n        ? Math.max(entry.expire, MIN_PRERENDERABLE_EXPIRE)\n        : entry.revalidate\n\n      if (\n        performance.timeOrigin + performance.now() >\n        entry.timestamp + maxAgeSeconds * 1000\n      ) {\n        debug?.('get', cacheKey, 'expired')\n\n        return undefined\n      }\n\n      let revalidate = entry.revalidate\n\n      if (areTagsExpired(entry.tags, entry.timestamp)) {\n        debug?.('get', cacheKey, 'had expired tag')\n        return undefined\n      }\n\n      if (areTagsStale(entry.tags, entry.timestamp)) {\n        debug?.('get', cacheKey, 'had stale tag')\n        revalidate = -1\n      }\n\n      const [returnStream, newSaved] = entry.value.tee()\n      entry.value = newSaved\n\n      debug?.('get', cacheKey, 'found', {\n        tags: entry.tags,\n        timestamp: entry.timestamp,\n        expire: entry.expire,\n        revalidate,\n      })\n\n      return {\n        ...entry,\n        revalidate,\n        value: returnStream,\n      }\n    },\n\n    async set(cacheKey, pendingEntry) {\n      debug?.('set', cacheKey, 'start')\n\n      let resolvePending: () => void = () => {}\n      const pendingPromise = new Promise<void>((resolve) => {\n        resolvePending = resolve\n      })\n      pendingSets.set(cacheKey, pendingPromise)\n\n      const entry = await pendingEntry\n\n      let size = 0\n\n      try {\n        // In production an `expire: 0` entry is dynamic: the \"use cache\"\n        // wrapper regenerates it on every read instead of serving the stored\n        // copy, so persisting it would be a wasted write of a value that is\n        // never served back. Skip storing it so the next read is a plain miss.\n        // The dev server keeps it, because its minimum retention serves the\n        // previously cached value across reloads. The `finally` below still\n        // resolves the pending set.\n        if (!process.env.__NEXT_DEV_SERVER && entry.expire === 0) {\n          debug?.('set', cacheKey, 'skipped dynamic entry')\n          return\n        }\n\n        const [value, clonedValue] = entry.value.tee()\n        entry.value = value\n        const reader = clonedValue.getReader()\n\n        for (let chunk; !(chunk = await reader.read()).done; ) {\n          size += Buffer.from(chunk.value).byteLength\n        }\n\n        memoryCache.set(cacheKey, {\n          entry,\n          isErrored: false,\n          errorRetryCount: 0,\n          size,\n        })\n\n        debug?.('set', cacheKey, 'done')\n      } catch (err) {\n        // TODO: store partial buffer with error after we retry 3 times\n        debug?.('set', cacheKey, 'failed', err)\n      } finally {\n        resolvePending()\n        pendingSets.delete(cacheKey)\n      }\n    },\n\n    async refreshTags() {\n      // Nothing to do for an in-memory cache handler.\n    },\n\n    async getExpiration(tags) {\n      const expirations = tags.map((tag) => {\n        const entry = tagsManifest.get(tag)\n        if (!entry) return 0\n        // Return the most recent timestamp (either expired or stale)\n        return entry.expired || 0\n      })\n\n      const expiration = Math.max(...expirations, 0)\n\n      debug?.('getExpiration', { tags, expiration })\n\n      return expiration\n    },\n\n    async updateTags(tags, durations) {\n      const now = Math.round(performance.timeOrigin + performance.now())\n      debug?.('updateTags', { tags, timestamp: now })\n\n      for (const tag of tags) {\n        // TODO: update file-system-cache?\n        const existingEntry = tagsManifest.get(tag) || {}\n\n        if (durations) {\n          // Use provided durations directly\n          const updates: TagManifestEntry = { ...existingEntry }\n\n          // mark as stale immediately\n          updates.stale = now\n\n          if (durations.expire !== undefined) {\n            updates.expired = now + durations.expire * 1000 // Convert seconds to ms\n          }\n\n          tagsManifest.set(tag, updates)\n        } else {\n          // Update expired field for immediate expiration (default behavior when no durations provided)\n          tagsManifest.set(tag, { ...existingEntry, expired: now })\n        }\n      }\n    },\n  }\n}\n","/**\n * Node in the doubly-linked list used for LRU tracking.\n * Each node represents a cache entry with bidirectional pointers.\n */\nclass LRUNode<T> {\n  public readonly key: string\n  public data: T\n  public size: number\n  public prev: LRUNode<T> | SentinelNode<T> | null = null\n  public next: LRUNode<T> | SentinelNode<T> | null = null\n\n  constructor(key: string, data: T, size: number) {\n    this.key = key\n    this.data = data\n    this.size = size\n  }\n}\n\n/**\n * Sentinel node used for head/tail boundaries.\n * These nodes don't contain actual cache data but simplify list operations.\n */\nclass SentinelNode<T> {\n  public prev: LRUNode<T> | SentinelNode<T> | null = null\n  public next: LRUNode<T> | SentinelNode<T> | null = null\n}\n\n/**\n * LRU (Least Recently Used) Cache implementation using a doubly-linked list\n * and hash map for O(1) operations.\n *\n * Algorithm:\n * - Uses a doubly-linked list to maintain access order (most recent at head)\n * - Hash map provides O(1) key-to-node lookup\n * - Sentinel head/tail nodes simplify edge case handling\n * - Size-based eviction supports custom size calculation functions\n *\n * Data Structure Layout:\n * HEAD <-> [most recent] <-> ... <-> [least recent] <-> TAIL\n *\n * Operations:\n * - get(): Move accessed node to head (mark as most recent)\n * - set(): Add new node at head, evict from tail if over capacity\n * - Eviction: Remove least recent node (tail.prev) when size exceeds limit\n */\nexport class LRUCache<T> {\n  private readonly cache: Map<string, LRUNode<T>> = new Map()\n  private readonly head: SentinelNode<T>\n  private readonly tail: SentinelNode<T>\n  private totalSize: number = 0\n  private readonly maxSize: number\n  private readonly calculateSize:\n    | ((value: T, key: string) => number)\n    | undefined\n  private readonly onEvict: ((key: string, value: T) => void) | undefined\n\n  constructor(\n    maxSize: number,\n    calculateSize?: (value: T, key: string) => number,\n    onEvict?: (key: string, value: T) => void\n  ) {\n    this.maxSize = maxSize\n    this.calculateSize = calculateSize\n    this.onEvict = onEvict\n\n    // Create sentinel nodes to simplify doubly-linked list operations\n    // HEAD <-> TAIL (empty list)\n    this.head = new SentinelNode<T>()\n    this.tail = new SentinelNode<T>()\n    this.head.next = this.tail\n    this.tail.prev = this.head\n  }\n\n  /**\n   * Adds a node immediately after the head (marks as most recently used).\n   * Used when inserting new items or when an item is accessed.\n   * PRECONDITION: node must be disconnected (prev/next should be null)\n   */\n  private addToHead(node: LRUNode<T>): void {\n    node.prev = this.head\n    node.next = this.head.next\n    // head.next is always non-null (points to tail or another node)\n    this.head.next!.prev = node\n    this.head.next = node\n  }\n\n  /**\n   * Removes a node from its current position in the doubly-linked list.\n   * Updates the prev/next pointers of adjacent nodes to maintain list integrity.\n   * PRECONDITION: node must be connected (prev/next are non-null)\n   */\n  private removeNode(node: LRUNode<T>): void {\n    // Connected nodes always have non-null prev/next\n    node.prev!.next = node.next\n    node.next!.prev = node.prev\n  }\n\n  /**\n   * Moves an existing node to the head position (marks as most recently used).\n   * This is the core LRU operation - accessed items become most recent.\n   */\n  private moveToHead(node: LRUNode<T>): void {\n    this.removeNode(node)\n    this.addToHead(node)\n  }\n\n  /**\n   * Removes and returns the least recently used node (the one before tail).\n   * This is called during eviction when the cache exceeds capacity.\n   * PRECONDITION: cache is not empty (ensured by caller)\n   */\n  private removeTail(): LRUNode<T> {\n    const lastNode = this.tail.prev as LRUNode<T>\n    // tail.prev is always non-null and always LRUNode when cache is not empty\n    this.removeNode(lastNode)\n    return lastNode\n  }\n\n  /**\n   * Sets a key-value pair in the cache.\n   * If the key exists, updates the value and moves to head.\n   * If new, adds at head and evicts from tail if necessary.\n   *\n   * Time Complexity:\n   * - O(1) for uniform item sizes\n   * - O(k) where k is the number of items evicted (can be O(N) for variable sizes)\n   */\n  public set(key: string, value: T): boolean {\n    const size = this.calculateSize?.(value, key) ?? 1\n    if (size <= 0) {\n      throw new Error(\n        `LRUCache: calculateSize returned ${size}, but size must be > 0. ` +\n          `Items with size 0 would never be evicted, causing unbounded cache growth.`\n      )\n    }\n    if (size > this.maxSize) {\n      console.warn('Single item size exceeds maxSize')\n      return false\n    }\n\n    const existing = this.cache.get(key)\n    if (existing) {\n      // Update existing node: adjust size and move to head (most recent)\n      existing.data = value\n      this.totalSize = this.totalSize - existing.size + size\n      existing.size = size\n      this.moveToHead(existing)\n    } else {\n      // Add new node at head (most recent position)\n      const newNode = new LRUNode(key, value, size)\n      this.cache.set(key, newNode)\n      this.addToHead(newNode)\n      this.totalSize += size\n    }\n\n    // Evict least recently used items until under capacity\n    while (this.totalSize > this.maxSize && this.cache.size > 0) {\n      const tail = this.removeTail()\n      this.cache.delete(tail.key)\n      this.totalSize -= tail.size\n      this.onEvict?.(tail.key, tail.data)\n    }\n\n    return true\n  }\n\n  /**\n   * Checks if a key exists in the cache.\n   * This is a pure query operation - does NOT update LRU order.\n   *\n   * Time Complexity: O(1)\n   */\n  public has(key: string): boolean {\n    return this.cache.has(key)\n  }\n\n  /**\n   * Retrieves a value by key and marks it as most recently used.\n   * Moving to head maintains the LRU property for future evictions.\n   *\n   * Time Complexity: O(1)\n   */\n  public get(key: string): T | undefined {\n    const node = this.cache.get(key)\n    if (!node) return undefined\n\n    // Mark as most recently used by moving to head\n    this.moveToHead(node)\n\n    return node.data\n  }\n\n  /**\n   * Returns an iterator over the cache entries. The order is outputted in the\n   * order of most recently used to least recently used.\n   */\n  public *[Symbol.iterator](): IterableIterator<[string, T]> {\n    let current = this.head.next\n    while (current && current !== this.tail) {\n      // Between head and tail, current is always LRUNode\n      const node = current as LRUNode<T>\n      yield [node.key, node.data]\n      current = current.next\n    }\n  }\n\n  /**\n   * Removes a specific key from the cache.\n   * Updates both the hash map and doubly-linked list.\n   *\n   * Note: This is an explicit removal and does NOT trigger the `onEvict`\n   * callback. Use this for intentional deletions where eviction tracking\n   * is not needed.\n   *\n   * Time Complexity: O(1)\n   */\n  public remove(key: string): void {\n    const node = this.cache.get(key)\n    if (!node) return\n\n    this.removeNode(node)\n    this.cache.delete(key)\n    this.totalSize -= node.size\n  }\n\n  /**\n   * Returns the number of items in the cache.\n   */\n  public get size(): number {\n    return this.cache.size\n  }\n\n  /**\n   * Returns the current total size of all cached items.\n   * This uses the custom size calculation if provided.\n   */\n  public get currentSize(): number {\n    return this.totalSize\n  }\n}\n","import type { CacheFs } from '../../shared/lib/utils'\n\nimport fs from 'fs'\nimport { randomUUID } from 'node:crypto'\n\nexport const nodeFs: CacheFs = {\n  existsSync: fs.existsSync,\n  readFile: fs.promises.readFile,\n  readFileSync: fs.readFileSync,\n  writeFile: (f, d) => fs.promises.writeFile(f, d),\n  writeFileAtomic: async (f, d) => {\n    const temporary = `${f}.${randomUUID()}.tmp`\n    try {\n      await fs.promises.writeFile(temporary, d)\n      await fs.promises.link(temporary, f)\n      return true\n    } catch (error) {\n      if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false\n      throw error\n    } finally {\n      await fs.promises.unlink(temporary).catch(() => {})\n    }\n  },\n  mkdir: (dir) => fs.promises.mkdir(dir, { recursive: true }),\n  stat: (f) => fs.promises.stat(f),\n}\n","const REACT_POSTPONE_TYPE: symbol = Symbol.for('react.postpone')\n\nexport function isPostpone(error: any): boolean {\n  return (\n    typeof error === 'object' &&\n    error !== null &&\n    error.$$typeof === REACT_POSTPONE_TYPE\n  )\n}\n","/**\n * Contains predefined constants for the trace span name in next/server.\n *\n * Currently, next/server/tracer is internal implementation only for tracking\n * next.js's implementation only with known span names defined here.\n **/\n\n// eslint typescript has a bug with TS enums\n\nenum BaseServerSpan {\n  handleRequest = 'BaseServer.handleRequest',\n  run = 'BaseServer.run',\n  pipe = 'BaseServer.pipe',\n  getStaticHTML = 'BaseServer.getStaticHTML',\n  render = 'BaseServer.render',\n  renderToResponseWithComponents = 'BaseServer.renderToResponseWithComponents',\n  renderToResponse = 'BaseServer.renderToResponse',\n  renderToHTML = 'BaseServer.renderToHTML',\n  renderError = 'BaseServer.renderError',\n  renderErrorToResponse = 'BaseServer.renderErrorToResponse',\n  renderErrorToHTML = 'BaseServer.renderErrorToHTML',\n  render404 = 'BaseServer.render404',\n}\n\nenum LoadComponentsSpan {\n  loadDefaultErrorComponents = 'LoadComponents.loadDefaultErrorComponents',\n  loadComponents = 'LoadComponents.loadComponents',\n}\n\nenum NextServerSpan {\n  getRequestHandler = 'NextServer.getRequestHandler',\n  getRequestHandlerWithMetadata = 'NextServer.getRequestHandlerWithMetadata',\n  getServer = 'NextServer.getServer',\n  getServerRequestHandler = 'NextServer.getServerRequestHandler',\n  createServer = 'createServer.createServer',\n}\n\nenum NextNodeServerSpan {\n  compression = 'NextNodeServer.compression',\n  getBuildId = 'NextNodeServer.getBuildId',\n  createComponentTree = 'NextNodeServer.createComponentTree',\n  clientComponentLoading = 'NextNodeServer.clientComponentLoading',\n  getLayoutOrPageModule = 'NextNodeServer.getLayoutOrPageModule',\n  generateStaticRoutes = 'NextNodeServer.generateStaticRoutes',\n  generateFsStaticRoutes = 'NextNodeServer.generateFsStaticRoutes',\n  generatePublicRoutes = 'NextNodeServer.generatePublicRoutes',\n  generateImageRoutes = 'NextNodeServer.generateImageRoutes.route',\n  sendRenderResult = 'NextNodeServer.sendRenderResult',\n  proxyRequest = 'NextNodeServer.proxyRequest',\n  runApi = 'NextNodeServer.runApi',\n  render = 'NextNodeServer.render',\n  renderHTML = 'NextNodeServer.renderHTML',\n  imageOptimizer = 'NextNodeServer.imageOptimizer',\n  getPagePath = 'NextNodeServer.getPagePath',\n  getRoutesManifest = 'NextNodeServer.getRoutesManifest',\n  findPageComponents = 'NextNodeServer.findPageComponents',\n  getFontManifest = 'NextNodeServer.getFontManifest',\n  getServerComponentManifest = 'NextNodeServer.getServerComponentManifest',\n  getRequestHandler = 'NextNodeServer.getRequestHandler',\n  renderToHTML = 'NextNodeServer.renderToHTML',\n  renderError = 'NextNodeServer.renderError',\n  renderErrorToHTML = 'NextNodeServer.renderErrorToHTML',\n  render404 = 'NextNodeServer.render404',\n  startResponse = 'NextNodeServer.startResponse',\n\n  // nested inner span, does not require parent scope name\n  route = 'route',\n  onProxyReq = 'onProxyReq',\n  apiResolver = 'apiResolver',\n  internalFetch = 'internalFetch',\n}\n\nenum StartServerSpan {\n  startServer = 'startServer.startServer',\n}\n\nenum RenderSpan {\n  getServerSideProps = 'Render.getServerSideProps',\n  getStaticProps = 'Render.getStaticProps',\n  renderToString = 'Render.renderToString',\n  renderDocument = 'Render.renderDocument',\n  createBodyResult = 'Render.createBodyResult',\n}\n\nenum AppRenderSpan {\n  renderToString = 'AppRender.renderToString',\n  renderToReadableStream = 'AppRender.renderToReadableStream',\n  getBodyResult = 'AppRender.getBodyResult',\n  fetch = 'AppRender.fetch',\n  waitShellReady = 'AppRender.waitShellReady',\n  renderToNodeFizzStream = 'AppRender.renderToNodeFizzStream',\n  instantInsights = 'AppRender.instantInsights',\n  instantInsightsPrepareValidation = 'AppRender.instantInsights.prepareValidation',\n  instantInsightsRunValidation = 'AppRender.instantInsights.runValidation',\n}\n\nenum RouterSpan {\n  executeRoute = 'Router.executeRoute',\n}\n\nenum NodeSpan {\n  runHandler = 'Node.runHandler',\n}\n\nenum AppRouteRouteHandlersSpan {\n  runHandler = 'AppRouteRouteHandlers.runHandler',\n}\n\nenum ResolveMetadataSpan {\n  generateMetadata = 'ResolveMetadata.generateMetadata',\n  generateViewport = 'ResolveMetadata.generateViewport',\n}\n\nenum MiddlewareSpan {\n  execute = 'Middleware.execute',\n}\n\ntype SpanTypes =\n  | `${BaseServerSpan}`\n  | `${LoadComponentsSpan}`\n  | `${NextServerSpan}`\n  | `${StartServerSpan}`\n  | `${NextNodeServerSpan}`\n  | `${RenderSpan}`\n  | `${RouterSpan}`\n  | `${AppRenderSpan}`\n  | `${NodeSpan}`\n  | `${AppRouteRouteHandlersSpan}`\n  | `${ResolveMetadataSpan}`\n  | `${MiddlewareSpan}`\n\n// This list is used to filter out spans that are not relevant to the user\nexport const NextVanillaSpanAllowlist = new Set([\n  MiddlewareSpan.execute,\n  BaseServerSpan.handleRequest,\n  RenderSpan.getServerSideProps,\n  RenderSpan.getStaticProps,\n  AppRenderSpan.fetch,\n  AppRenderSpan.getBodyResult,\n  RenderSpan.renderDocument,\n  NodeSpan.runHandler,\n  AppRouteRouteHandlersSpan.runHandler,\n  ResolveMetadataSpan.generateMetadata,\n  ResolveMetadataSpan.generateViewport,\n  NextNodeServerSpan.createComponentTree,\n  NextNodeServerSpan.findPageComponents,\n  NextNodeServerSpan.getLayoutOrPageModule,\n  NextNodeServerSpan.startResponse,\n  NextNodeServerSpan.clientComponentLoading,\n])\n\n// These Spans are allowed to be always logged\n// when the otel log prefix env is set\nexport const LogSpanAllowList = new Set([\n  NextNodeServerSpan.findPageComponents,\n  NextNodeServerSpan.createComponentTree,\n  NextNodeServerSpan.clientComponentLoading,\n])\n\nexport {\n  BaseServerSpan,\n  LoadComponentsSpan,\n  NextServerSpan,\n  NextNodeServerSpan,\n  StartServerSpan,\n  RenderSpan,\n  RouterSpan,\n  AppRenderSpan,\n  NodeSpan,\n  AppRouteRouteHandlersSpan,\n  ResolveMetadataSpan,\n  MiddlewareSpan,\n}\n\nexport type { SpanTypes }\n","import type { AsyncLocalStorage } from 'async_hooks'\nimport type { RequestInsightKind } from '../../../next-devtools/shared/request-insights'\nimport { createAsyncLocalStorage } from '../../app-render/async-local-storage'\n\nexport type RequestInsightsIdentity = {\n  requestId: string\n  kind?: RequestInsightKind\n  htmlRequestId: string\n  url: string | undefined\n}\n\n// This storage covers the part of BaseServer request handling that runs before\n// App Render creates workAsyncStorage. Once available, workStore remains the\n// primary identity source for locally recorded spans.\nconst REQUEST_INSIGHTS_IDENTITY_STORAGE_KEY = Symbol.for(\n  '@next/request-insights-identity-storage'\n)\n\nfunction getRequestInsightsIdentityStorage(): AsyncLocalStorage<RequestInsightsIdentity> {\n  const globalStore = globalThis as typeof globalThis & {\n    [REQUEST_INSIGHTS_IDENTITY_STORAGE_KEY]?: AsyncLocalStorage<RequestInsightsIdentity>\n  }\n\n  return (globalStore[REQUEST_INSIGHTS_IDENTITY_STORAGE_KEY] ??=\n    createAsyncLocalStorage())\n}\n\nexport function runWithRequestInsightsIdentity<T>(\n  identity: RequestInsightsIdentity,\n  fn: () => T\n): T {\n  return getRequestInsightsIdentityStorage().run(identity, fn)\n}\n\nexport function getRequestInsightsIdentity():\n  | RequestInsightsIdentity\n  | undefined {\n  return getRequestInsightsIdentityStorage().getStore()\n}\n","export type RequestInsightKind = 'request' | 'instant-insights'\n\nexport type RequestInsightIdentity = {\n  requestId: string\n  kind?: RequestInsightKind\n}\n\nexport function getRequestInsightKind(\n  insight: Pick<RequestInsightIdentity, 'kind'>\n): RequestInsightKind {\n  return insight.kind ?? 'request'\n}\n\nexport function getRequestInsightKey(insight: RequestInsightIdentity): string {\n  return `${getRequestInsightKind(insight)}:${insight.requestId}`\n}\n","import type { AttributeValue } from 'next/dist/compiled/@opentelemetry/api'\nimport type {\n  RequestInsight,\n  RequestInsightFetch,\n  RequestInsightsSnapshot,\n} from '../../../next-devtools/shared/request-insights'\nimport type { RequestInsightKind } from '../../../shared/lib/request-insights'\nimport {\n  getRequestInsightKey,\n  getRequestInsightKind,\n} from '../../../shared/lib/request-insights'\nimport type { SpanStoreRecord } from './span-store'\nexport { isRequestInsightsEnabled } from './span-store'\n\nconst MAX_REQUEST_INSIGHTS = 100\nconst REQUEST_INSIGHTS_STORE_KEY = Symbol.for('@next/request-insights-store')\nconst CLIENT_COMPONENT_LOADING_SPAN_TYPE =\n  'NextNodeServer.clientComponentLoading'\n\ntype RequestInsightsListener = (insight: RequestInsight) => void\ntype RequestInsightIdentity = {\n  requestId?: string\n  kind?: RequestInsightKind\n  htmlRequestId?: string\n  route?: string\n  url?: string\n}\n\nconst REDACTED_VALUE = 'redacted'\nconst SAFE_SPAN_ATTRIBUTE_KEYS = new Set([\n  'http.method',\n  'http.route',\n  'http.status_code',\n  'http.url',\n  'net.peer.name',\n  'net.peer.port',\n  'next.fetch.cache_reason',\n  'next.fetch.cache_status',\n  'next.fetch.idx',\n  'next.route',\n  'next.rsc',\n  'next.segment',\n  'next.span_category',\n  'next.span_name',\n  'next.span_type',\n])\nconst SENSITIVE_PARAM_NAME_RE =\n  /(?:^|[_-])(?:access[_-]?token|api[_-]?key|auth|authorization|code|cookie|credential|id[_-]?token|jwt|key|password|secret|session|signature|sig|token)(?:$|[_-])/i\n\nclass InMemoryRequestInsightsStore {\n  private readonly requests = new Map<string, RequestInsight>()\n  private readonly requestTimings = new Map<\n    string,\n    { startTime: number; durationMs: number }\n  >()\n  private readonly requestOrder: string[] = []\n  private readonly listeners = new Set<RequestInsightsListener>()\n\n  recordSpan(span: SpanStoreRecord): void {\n    if (!span.requestId) {\n      return\n    }\n\n    const insight = this.getOrCreateRequest(\n      {\n        requestId: span.requestId,\n        kind: span.requestInsightKind,\n        htmlRequestId: span.htmlRequestId,\n        route: span.route,\n        url: span.url,\n      },\n      span.startTime ?? span.timestamp\n    )\n\n    const spanStartTime = span.startTime ?? span.timestamp\n    insight.htmlRequestId = span.htmlRequestId ?? insight.htmlRequestId\n    insight.route = insight.route ?? span.route\n    insight.url = insight.url ?? sanitizeUrl(span.url)\n    this.updateTiming(\n      insight,\n      spanStartTime,\n      span.durationMs,\n      span.attributes?.['next.span_type'] === 'BaseServer.handleRequest'\n    )\n    insight.status =\n      insight.status === 'error' || span.status === 'error'\n        ? 'error'\n        : span.status === 'ok'\n          ? 'ok'\n          : insight.status\n\n    insight.spans.push({\n      name: span.name,\n      startTime: spanStartTime,\n      durationMs: span.durationMs,\n      status: span.status,\n      traceId: span.traceId,\n      spanId: span.spanId,\n      parentSpanId: span.parentSpanId,\n      attributes: sanitizeSpanAttributes(span.attributes),\n      links: sanitizeSpanLinks(span.links),\n      events: sanitizeSpanEvents(span.events),\n      error: span.error,\n    })\n\n    const fetch = getFetchInsight(span)\n    if (fetch) {\n      this.recordFetchForInsight(insight, fetch)\n    }\n\n    this.notify(insight)\n  }\n\n  recordFetch(identity: RequestInsightIdentity, fetch: RequestInsightFetch) {\n    if (!identity.requestId) {\n      return\n    }\n\n    const fetchStartTime = fetch.startTime ?? getCurrentTimestamp()\n    const insight = this.getOrCreateRequest(identity, fetchStartTime)\n    this.updateTiming(insight, fetchStartTime, fetch.durationMs, false)\n    this.recordFetchForInsight(insight, sanitizeFetchInsight(fetch))\n    this.notify(insight)\n  }\n\n  getSnapshot(): RequestInsightsSnapshot {\n    return {\n      requests: this.requestOrder\n        .map((insightKey) => this.requests.get(insightKey))\n        .filter((request): request is RequestInsight => request !== undefined),\n    }\n  }\n\n  subscribe(listener: RequestInsightsListener): () => void {\n    this.listeners.add(listener)\n    return () => {\n      this.listeners.delete(listener)\n    }\n  }\n\n  clear(): void {\n    this.requests.clear()\n    this.requestTimings.clear()\n    this.requestOrder.length = 0\n  }\n\n  private updateTiming(\n    insight: RequestInsight,\n    startTime: number,\n    durationMs: number | undefined,\n    isRequestSpan: boolean\n  ): void {\n    const insightKey = getRequestInsightKey(insight)\n    if (isRequestSpan && durationMs !== undefined) {\n      const requestTiming = { startTime, durationMs }\n      this.requestTimings.set(insightKey, requestTiming)\n      insight.startTime = requestTiming.startTime\n      insight.durationMs = requestTiming.durationMs\n      return\n    }\n\n    const requestTiming = this.requestTimings.get(insightKey)\n    if (requestTiming) {\n      insight.startTime = requestTiming.startTime\n      insight.durationMs = requestTiming.durationMs\n      return\n    }\n\n    const endTime = startTime + (durationMs ?? 0)\n    const requestEndTime = insight.startTime + (insight.durationMs ?? 0)\n    insight.startTime = Math.min(insight.startTime, startTime)\n    insight.durationMs = Math.max(requestEndTime, endTime) - insight.startTime\n  }\n\n  private notify(insight: RequestInsight): void {\n    for (const listener of this.listeners) {\n      listener(insight)\n    }\n  }\n\n  private getOrCreateRequest(\n    identity: RequestInsightIdentity,\n    startTime: number\n  ): RequestInsight {\n    const requestId = identity.requestId!\n    const insightKey = getRequestInsightKey({\n      requestId,\n      kind: identity.kind,\n    })\n    let insight = this.requests.get(insightKey)\n\n    if (!insight) {\n      insight = {\n        requestId,\n        kind: getRequestInsightKind(identity),\n        htmlRequestId: identity.htmlRequestId ?? requestId,\n        route: identity.route,\n        url: sanitizeUrl(identity.url),\n        startTime,\n        status: 'pending',\n        spans: [],\n        fetches: [],\n      }\n      this.requests.set(insightKey, insight)\n      this.requestOrder.push(insightKey)\n      this.trim()\n    }\n\n    insight.htmlRequestId = identity.htmlRequestId ?? insight.htmlRequestId\n    insight.route = insight.route ?? identity.route\n    insight.url = insight.url ?? sanitizeUrl(identity.url)\n    insight.startTime = Math.min(insight.startTime, startTime)\n\n    return insight\n  }\n\n  private recordFetchForInsight(\n    insight: RequestInsight,\n    fetch: RequestInsightFetch\n  ): void {\n    if (\n      insight.fetches.some(\n        (existingFetch) =>\n          existingFetch.url === fetch.url &&\n          (existingFetch.index !== undefined && fetch.index !== undefined\n            ? existingFetch.index === fetch.index\n            : existingFetch.startTime === fetch.startTime)\n      )\n    ) {\n      return\n    }\n\n    insight.fetches.push(sanitizeFetchInsight(fetch))\n  }\n\n  private trim(): void {\n    while (this.requestOrder.length > MAX_REQUEST_INSIGHTS) {\n      const insightKey = this.requestOrder.shift()\n      if (insightKey) {\n        this.requests.delete(insightKey)\n        this.requestTimings.delete(insightKey)\n      }\n    }\n  }\n}\n\nexport function recordRequestInsightSpan(span: SpanStoreRecord): void {\n  if (\n    span.attributes?.['next.span_type'] === CLIENT_COMPONENT_LOADING_SPAN_TYPE\n  ) {\n    return\n  }\n\n  getRequestInsightsStore().recordSpan(span)\n}\n\nexport function recordRequestInsightFetch(\n  identity: RequestInsightIdentity,\n  fetch: RequestInsightFetch\n): void {\n  getRequestInsightsStore().recordFetch(identity, fetch)\n}\n\nexport function getRequestInsightsSnapshot(): RequestInsightsSnapshot {\n  return getRequestInsightsStore().getSnapshot()\n}\n\nexport function subscribeRequestInsights(\n  listener: RequestInsightsListener\n): () => void {\n  return getRequestInsightsStore().subscribe(listener)\n}\n\nexport function clearRequestInsightsForTest(): void {\n  getRequestInsightsStore().clear()\n}\n\nfunction getRequestInsightsStore(): InMemoryRequestInsightsStore {\n  const globalStore = globalThis as typeof globalThis & {\n    [REQUEST_INSIGHTS_STORE_KEY]?: InMemoryRequestInsightsStore\n  }\n\n  return (globalStore[REQUEST_INSIGHTS_STORE_KEY] ??=\n    new InMemoryRequestInsightsStore())\n}\n\nfunction getFetchInsight(span: SpanStoreRecord): RequestInsightFetch | null {\n  const attributes = span.attributes\n\n  if (!attributes || attributes['next.span_type'] !== 'AppRender.fetch') {\n    return null\n  }\n\n  return {\n    url: sanitizeUrl(getStringAttribute(attributes['http.url']) ?? span.url),\n    method: getStringAttribute(attributes['http.method']),\n    statusCode: getNumberAttribute(attributes['http.status_code']),\n    startTime: span.startTime ?? span.timestamp,\n    durationMs: span.durationMs,\n    cacheStatus: getStringAttribute(attributes['next.fetch.cache_status']),\n    cacheReason: getStringAttribute(attributes['next.fetch.cache_reason']),\n    index: getNumberAttribute(attributes['next.fetch.idx']),\n  }\n}\n\nfunction sanitizeFetchInsight(fetch: RequestInsightFetch): RequestInsightFetch {\n  return {\n    ...fetch,\n    url: sanitizeUrl(fetch.url),\n  }\n}\n\nfunction getCurrentTimestamp(): number {\n  return performance.timeOrigin + performance.now()\n}\n\nfunction sanitizeSpanAttributes(\n  attributes: SpanStoreRecord['attributes']\n): SpanStoreRecord['attributes'] {\n  if (!attributes) {\n    return undefined\n  }\n\n  const sanitized: NonNullable<SpanStoreRecord['attributes']> = {}\n  for (const [key, value] of Object.entries(attributes)) {\n    if (!SAFE_SPAN_ATTRIBUTE_KEYS.has(key)) {\n      continue\n    }\n\n    sanitized[key] = key === 'http.url' ? sanitizeUrlAttribute(value) : value\n  }\n\n  return Object.keys(sanitized).length > 0 ? sanitized : undefined\n}\n\nfunction sanitizeSpanEvents(\n  events: SpanStoreRecord['events']\n): SpanStoreRecord['events'] {\n  return events?.map((event) => ({\n    ...event,\n    attributes: sanitizeSpanAttributes(event.attributes),\n  }))\n}\n\nfunction sanitizeSpanLinks(\n  links: SpanStoreRecord['links']\n): SpanStoreRecord['links'] {\n  return links?.map((link) => ({\n    ...link,\n    attributes: sanitizeSpanAttributes(link.attributes),\n  }))\n}\n\nfunction sanitizeUrlAttribute(value: AttributeValue): AttributeValue {\n  return typeof value === 'string' ? (sanitizeUrl(value) ?? '') : value\n}\n\nfunction sanitizeUrl(value: string | undefined): string | undefined {\n  if (!value) {\n    return value\n  }\n\n  const isRelativeUrl = value.startsWith('/')\n\n  try {\n    const url = isRelativeUrl ? new URL(value, 'http://n') : new URL(value)\n\n    url.username = ''\n    url.password = ''\n\n    for (const name of Array.from(url.searchParams.keys())) {\n      if (SENSITIVE_PARAM_NAME_RE.test(name)) {\n        url.searchParams.set(name, REDACTED_VALUE)\n      }\n    }\n\n    return isRelativeUrl ? `${url.pathname}${url.search}${url.hash}` : url.href\n  } catch {\n    return value\n  }\n}\n\nfunction getStringAttribute(value: AttributeValue | undefined) {\n  return typeof value === 'string' ? value : undefined\n}\n\nfunction getNumberAttribute(value: AttributeValue | undefined) {\n  return typeof value === 'number' ? value : undefined\n}\n","import type { AttributeValue } from 'next/dist/compiled/@opentelemetry/api'\nimport type { RequestInsightKind } from '../../../next-devtools/shared/request-insights'\n\nexport type SpanStoreAttributes = Record<string, AttributeValue>\n\nexport type SpanStoreLink = {\n  traceId: string\n  spanId: string\n  attributes?: SpanStoreAttributes\n}\n\nexport type SpanStoreEvent = {\n  name: string\n  timestamp: number\n  attributes?: SpanStoreAttributes\n}\n\nexport type SpanStoreRecord = {\n  name: string\n  timestamp: number\n  startTime?: number\n  durationMs?: number\n  status?: 'ok' | 'error'\n  traceId?: string\n  spanId?: string\n  parentSpanId?: string\n  requestId?: string\n  requestInsightKind?: RequestInsightKind\n  htmlRequestId?: string\n  route?: string\n  url?: string\n  attributes?: SpanStoreAttributes\n  links?: SpanStoreLink[]\n  events?: SpanStoreEvent[]\n  error?: {\n    type?: string\n    message?: string\n  }\n}\n\ntype SpanRecorderForTest = (span: SpanStoreRecord) => void\n\nlet spanRecorderForTest: SpanRecorderForTest | undefined\n\nexport function recordSpan(record: Omit<SpanStoreRecord, 'timestamp'>): void {\n  if (!isLocalSpanRecordingEnabled()) {\n    return\n  }\n\n  const spanRecord: SpanStoreRecord = {\n    timestamp: getCurrentTimestamp(),\n    ...record,\n  }\n\n  spanRecorderForTest?.(spanRecord)\n\n  if (isRequestInsightsEnabled() && spanRecord.requestId) {\n    const { recordRequestInsightSpan } =\n      require('./request-insights') as typeof import('./request-insights')\n    recordRequestInsightSpan(spanRecord)\n  }\n}\n\nexport function setSpanRecorderForTest(\n  recorder: SpanRecorderForTest | undefined\n): void {\n  spanRecorderForTest = recorder\n}\n\nexport function isLocalSpanRecordingEnabled(): boolean {\n  if (!process.env.__NEXT_DEV_SERVER) {\n    return false\n  }\n\n  return spanRecorderForTest !== undefined || isRequestInsightsEnabled()\n}\n\nexport function isRequestInsightsEnabled(): boolean {\n  if (!process.env.__NEXT_DEV_SERVER) {\n    return false\n  }\n\n  const value = process.env.__NEXT_REQUEST_INSIGHTS\n  return isEnabledEnvValue(value)\n}\n\nfunction isEnabledEnvValue(value: string | undefined): boolean {\n  return value === '1' || value === 'true' || (value as unknown) === true\n}\n\nfunction getCurrentTimestamp(): number {\n  return performance.timeOrigin + performance.now()\n}\n","import { isPostpone } from '../lib/router-utils/is-postpone'\nimport * as Log from '../../build/output/log'\n\nlet _global = globalThis as typeof globalThis & {\n  nextInitializedProcessErrorHandlers?: boolean\n  [UNHANDLED_REJECTION_LISTENER_KEY]?: NodeJS.UnhandledRejectionListener\n}\n\n// The listener function is shared via globalThis so that multiple copies of\n// this module (e.g. in the pre-compiled server bundle and in a route module\n// bundle) still register and detect a single listener instance.\nconst UNHANDLED_REJECTION_LISTENER_KEY = Symbol.for(\n  'next.unhandledRejectionListener'\n)\n\nfunction unhandledRejectionListener(reason: unknown) {\n  if (isPostpone(reason)) {\n    // React postpones that are unhandled might end up logged here but they're\n    // not really errors. They're just part of rendering.\n    return\n  }\n  // Immediately log the error.\n  // TODO: Ideally, if we knew that this error was triggered by application\n  // code, we would suppress it entirely without logging. We can't reliably\n  // detect all of these, but when cacheComponents is enabled, we could suppress\n  // at least some of them by waiting to log the error until after all in-\n  // progress renders have completed. Then, only log errors for which there\n  // was not a corresponding \"rejectionHandled\" event.\n  Log.error('unhandledRejection:', reason)\n}\n\n/**\n * Checks if the Next.js unhandled rejection listener is currently attached.\n * This queries the actual process listeners instead of relying on a module\n * global, so it stays accurate even if the listener was removed externally,\n * e.g. via `process.removeAllListeners('unhandledRejection')`.\n */\nexport function isUnhandledRejectionListenerRegistered(): boolean {\n  const listener = _global[UNHANDLED_REJECTION_LISTENER_KEY]\n\n  return (\n    listener !== undefined &&\n    process.listeners('unhandledRejection').includes(listener)\n  )\n}\n\n/**\n * Registers the Next.js unhandled rejection listener, which logs unhandled\n * rejections (except React postpones) and prevents them from crashing the\n * process. Safe to call unconditionally: if the listener is already attached,\n * this is a no-op, so it never registers a duplicate.\n */\nexport function registerUnhandledRejectionListener(): void {\n  if (isUnhandledRejectionListenerRegistered()) {\n    return\n  }\n\n  const listener = (_global[UNHANDLED_REJECTION_LISTENER_KEY] ??=\n    unhandledRejectionListener)\n\n  process.on('unhandledRejection', listener)\n}\n\nexport function installProcessErrorHandlers(\n  shouldRemoveUncaughtErrorAndRejectionListeners: boolean\n) {\n  if (!_global.nextInitializedProcessErrorHandlers) {\n    _global.nextInitializedProcessErrorHandlers = true\n    // The conventional wisdom of Node.js and other runtimes is to treat\n    // unhandled errors as fatal and exit the process.\n    //\n    // But Next.js is not a generic JS runtime — it's a specialized runtime for\n    // React Server Components.\n    //\n    // Many unhandled rejections are due to the late-awaiting pattern for\n    // prefetching data. In Next.js it's OK to call an async function without\n    // immediately awaiting it, to start the request as soon as possible\n    // without blocking unncessarily on the result. These can end up\n    // triggering an \"unhandledRejection\" if it later turns out that the\n    // data is not needed to render the page. Example:\n    //\n    //     const promise = fetchData()\n    //     const shouldShow = await checkCondition()\n    //     if (shouldShow) {\n    //       return <Component promise={promise} />\n    //     }\n    //\n    // In this example, `fetchData` is called immediately to start the request\n    // as soon as possible, but if `shouldShow` is false, then it will be\n    // discarded without unwrapping its result. If it errors, it will trigger\n    // an \"unhandledRejection\" event.\n    //\n    // Ideally, we would suppress these rejections completely without warning,\n    // because we don't consider them real errors. (TODO: Currently we do warn.)\n    //\n    // But regardless of whether we do or don't warn, we definitely shouldn't\n    // crash the entire process.\n    //\n    // Even a \"legit\" unhandled error unrelated to prefetching shouldn't\n    // prevent the rest of the page from rendering.\n    //\n    // So, we're going to intentionally override the default error handling\n    // behavior of the outer JS runtime to be more forgiving\n\n    // Remove any existing \"unhandledRejection\" and \"uncaughtException\" handlers.\n    // This is gated behind an experimental flag until we've considered the impact\n    // in various deployment environments. It's possible this may always need to\n    // be configurable.\n    if (shouldRemoveUncaughtErrorAndRejectionListeners) {\n      process.removeAllListeners('uncaughtException')\n      process.removeAllListeners('unhandledRejection')\n    }\n\n    process.on('rejectionHandled', () => {\n      // TODO: See note in the unhandledRejection listener above. In the\n      // future, we may use the \"rejectionHandled\" event to de-queue an error\n      // from being logged.\n    })\n\n    // Unhandled exceptions are errors triggered by non-async functions, so this\n    // is unrelated to the late-awaiting pattern. However, for similar reasons,\n    // we still shouldn't crash the process. Just log it.\n    process.on('uncaughtException', (reason: unknown) => {\n      if (isPostpone(reason)) {\n        return\n      }\n      console.error(reason)\n    })\n  }\n\n  // Register the listener unconditionally, and not only during the guarded\n  // initialization above: a previous registration may have been undone by the\n  // `removeAllListeners` call of a later `installProcessErrorHandlers` call\n  // (or by external code), and registering is a no-op if the listener is\n  // still attached.\n  registerUnhandledRejectionListener()\n}\n","import type { WorkStore } from './app-render/work-async-storage.external'\nimport type { IncrementalCache } from './lib/incremental-cache'\nimport { getCacheHandlers } from './use-cache/handlers'\n\n/** Run a callback, and execute any *new* revalidations added during its runtime. */\nexport async function withExecuteRevalidates<T>(\n  store: WorkStore | undefined,\n  callback: () => Promise<T>\n): Promise<T> {\n  if (!store) {\n    return callback()\n  }\n  // If we executed any revalidates during the request, then we don't want to execute them again.\n  // save the state so we can check if anything changed after we're done running callbacks.\n  const savedRevalidationState = cloneRevalidationState(store)\n  try {\n    return await callback()\n  } finally {\n    // Check if we have any new revalidates, and if so, wait until they are all resolved.\n    const newRevalidates = diffRevalidationState(\n      savedRevalidationState,\n      cloneRevalidationState(store)\n    )\n    await executeRevalidates(store, newRevalidates)\n  }\n}\n\ntype RevalidationState = Required<\n  Pick<\n    WorkStore,\n    'pendingRevalidatedTags' | 'pendingRevalidates' | 'pendingRevalidateWrites'\n  >\n>\n\nfunction cloneRevalidationState(store: WorkStore): RevalidationState {\n  return {\n    pendingRevalidatedTags: store.pendingRevalidatedTags\n      ? [...store.pendingRevalidatedTags]\n      : [],\n    pendingRevalidates: { ...store.pendingRevalidates },\n    pendingRevalidateWrites: store.pendingRevalidateWrites\n      ? [...store.pendingRevalidateWrites]\n      : [],\n  }\n}\n\nfunction diffRevalidationState(\n  prev: RevalidationState,\n  curr: RevalidationState\n): RevalidationState {\n  const prevTagsWithProfile = new Set(\n    prev.pendingRevalidatedTags.map((item) => {\n      const profileKey =\n        typeof item.profile === 'object'\n          ? JSON.stringify(item.profile)\n          : item.profile || ''\n      return `${item.tag}:${profileKey}`\n    })\n  )\n  const prevRevalidateWrites = new Set(prev.pendingRevalidateWrites)\n  return {\n    pendingRevalidatedTags: curr.pendingRevalidatedTags.filter((item) => {\n      const profileKey =\n        typeof item.profile === 'object'\n          ? JSON.stringify(item.profile)\n          : item.profile || ''\n      return !prevTagsWithProfile.has(`${item.tag}:${profileKey}`)\n    }),\n    pendingRevalidates: Object.fromEntries(\n      Object.entries(curr.pendingRevalidates).filter(\n        ([key]) => !(key in prev.pendingRevalidates)\n      )\n    ),\n    pendingRevalidateWrites: curr.pendingRevalidateWrites.filter(\n      (promise) => !prevRevalidateWrites.has(promise)\n    ),\n  }\n}\n\nasync function revalidateTags(\n  tagsWithProfile: Array<{\n    tag: string\n    profile?: string | { expire?: number }\n  }>,\n  incrementalCache: IncrementalCache | undefined,\n  workStore?: WorkStore\n): Promise<void> {\n  if (tagsWithProfile.length === 0) {\n    return\n  }\n\n  const handlers = getCacheHandlers()\n  const promises: Promise<void>[] = []\n\n  // Group tags by profile for batch processing\n  const tagsByProfile = new Map<\n    | string\n    | { stale?: number; revalidate?: number; expire?: number }\n    | undefined,\n    string[]\n  >()\n\n  for (const item of tagsWithProfile) {\n    const profile = item.profile\n    // Find existing profile by comparing values\n    let existingKey = undefined\n    for (const [key] of tagsByProfile) {\n      if (\n        typeof key === 'string' &&\n        typeof profile === 'string' &&\n        key === profile\n      ) {\n        existingKey = key\n        break\n      }\n      if (\n        typeof key === 'object' &&\n        typeof profile === 'object' &&\n        JSON.stringify(key) === JSON.stringify(profile)\n      ) {\n        existingKey = key\n        break\n      }\n      if (key === profile) {\n        existingKey = key\n        break\n      }\n    }\n\n    const profileKey = existingKey || profile\n    if (!tagsByProfile.has(profileKey)) {\n      tagsByProfile.set(profileKey, [])\n    }\n    tagsByProfile.get(profileKey)!.push(item.tag)\n  }\n\n  // Process each profile group\n  for (const [profile, tagsForProfile] of tagsByProfile) {\n    // Look up the cache profile from workStore if available\n    let durations: { expire?: number } | undefined\n\n    if (profile) {\n      let cacheLife:\n        | { stale?: number; revalidate?: number; expire?: number }\n        | undefined\n\n      if (typeof profile === 'object') {\n        // Profile is already a cacheLife configuration object\n        cacheLife = profile\n      } else if (typeof profile === 'string') {\n        // Profile is a string key, look it up in workStore\n        cacheLife = workStore?.cacheLifeProfiles[profile]\n\n        if (!cacheLife) {\n          throw new Error(\n            `Invalid profile provided \"${profile}\" must be configured under cacheLife in next.config or be \"max\"`\n          )\n        }\n      }\n\n      if (cacheLife) {\n        durations = {\n          expire: cacheLife.expire,\n        }\n      }\n    }\n    // If profile is not found and not 'max', durations will be undefined\n    // which will trigger immediate expiration in the cache handler\n\n    for (const handler of handlers || []) {\n      if (profile) {\n        promises.push(handler.updateTags?.(tagsForProfile, durations))\n      } else {\n        promises.push(handler.updateTags?.(tagsForProfile))\n      }\n    }\n\n    if (incrementalCache) {\n      promises.push(incrementalCache.revalidateTag(tagsForProfile, durations))\n    }\n  }\n\n  await Promise.all(promises)\n}\n\nexport function executeRevalidates(\n  workStore: WorkStore,\n  state?: RevalidationState\n): false | Promise<void> {\n  const promises: Promise<unknown>[] = []\n\n  const pendingRevalidatedTags =\n    state?.pendingRevalidatedTags ?? workStore.pendingRevalidatedTags ?? []\n\n  if (pendingRevalidatedTags.length > 0) {\n    promises.push(\n      revalidateTags(\n        pendingRevalidatedTags,\n        workStore.incrementalCache,\n        workStore\n      )\n    )\n  }\n\n  const pendingRevalidates = Object.values(\n    state?.pendingRevalidates ?? workStore.pendingRevalidates ?? {}\n  )\n\n  promises.push(...pendingRevalidates)\n\n  const pendingRevalidateWrites =\n    state?.pendingRevalidateWrites ?? workStore.pendingRevalidateWrites ?? []\n\n  promises.push(...pendingRevalidateWrites)\n\n  if (promises.length === 0) {\n    return false\n  }\n\n  return Promise.all(promises).then(() => undefined)\n}\n","import * as React from 'react'\nimport * as ReactDOM from 'react-dom'\nimport * as ReactJsxDevRuntime from 'react/jsx-dev-runtime'\nimport * as ReactJsxRuntime from 'react/jsx-runtime'\nimport * as ReactCompilerRuntime from 'react/compiler-runtime'\n\nimport * as ReactDOMServer from 'react-dom/server'\n\nfunction getAltProxyForBindingsDEV(\n  type: 'Turbopack' | 'Webpack',\n  pkg: 'react-server-dom-turbopack/client' | 'react-server-dom-webpack/client'\n) {\n  if (process.env.NODE_ENV === 'development') {\n    const altType = type === 'Turbopack' ? 'Webpack' : 'Turbopack'\n    const altPkg = pkg.replace(new RegExp(type, 'gi'), altType.toLowerCase())\n\n    return new Proxy(\n      {},\n      {\n        get(_, prop: string) {\n          throw new Error(\n            `Expected to use ${type} bindings (${pkg}) for React but the current process is referencing '${prop}' from the ${altType} bindings (${altPkg}). This is likely a bug in our integration of the Next.js server runtime.`\n          )\n        },\n      }\n    )\n  }\n}\n\nlet ReactServerDOMTurbopackClient, ReactServerDOMWebpackClient\nif (process.env.TURBOPACK) {\n  ReactServerDOMTurbopackClient =\n    // @ts-expect-error -- TODO: Add types\n    // eslint-disable-next-line import/no-extraneous-dependencies\n    require('react-server-dom-turbopack/client') as typeof import('react-server-dom-turbopack/client')\n  if (process.env.NODE_ENV === 'development') {\n    ReactServerDOMWebpackClient = getAltProxyForBindingsDEV(\n      'Turbopack',\n      'react-server-dom-turbopack/client'\n    )\n  }\n} else {\n  ReactServerDOMWebpackClient =\n    // eslint-disable-next-line import/no-extraneous-dependencies\n    require('react-server-dom-webpack/client') as typeof import('react-server-dom-webpack/client')\n  if (process.env.NODE_ENV === 'development') {\n    ReactServerDOMTurbopackClient = getAltProxyForBindingsDEV(\n      'Webpack',\n      'react-server-dom-webpack/client'\n    )\n  }\n}\n\nexport {\n  React,\n  ReactJsxDevRuntime,\n  ReactJsxRuntime,\n  ReactCompilerRuntime,\n  ReactDOM,\n  ReactDOMServer,\n  ReactServerDOMTurbopackClient,\n  ReactServerDOMWebpackClient,\n}\n","export const ENCODED_TAGS = {\n  // opening tags do not have the closing `>` since they can contain other attributes such as `<body className=''>`\n  OPENING: {\n    // <html\n    HTML: new Uint8Array([60, 104, 116, 109, 108]),\n    // <head\n    HEAD: new Uint8Array([60, 104, 101, 97, 100]),\n    // <body\n    BODY: new Uint8Array([60, 98, 111, 100, 121]),\n  },\n  CLOSED: {\n    // </head>\n    HEAD: new Uint8Array([60, 47, 104, 101, 97, 100, 62]),\n    // </body>\n    BODY: new Uint8Array([60, 47, 98, 111, 100, 121, 62]),\n    // </html>\n    HTML: new Uint8Array([60, 47, 104, 116, 109, 108, 62]),\n    // </body></html>\n    BODY_AND_HTML: new Uint8Array([\n      60, 47, 98, 111, 100, 121, 62, 60, 47, 104, 116, 109, 108, 62,\n    ]),\n  },\n  META: {\n    // Only the match the prefix cause the suffix can be different wether it's xml compatible or not \">\" or \"/>\"\n    // <meta name=\"«nxt-icon»\"\n    // This is a special mark that will be replaced by the icon insertion script tag.\n    ICON_MARK: new Uint8Array([\n      60, 109, 101, 116, 97, 32, 110, 97, 109, 101, 61, 34, 194, 171, 110, 120,\n      116, 45, 105, 99, 111, 110, 194, 187, 34,\n    ]),\n  },\n} as const\n","import type { ReactDOMServerReadableStream } from 'react-dom/server'\nimport { getTracer } from '../lib/trace/tracer'\nimport { AppRenderSpan } from '../lib/trace/constants'\nimport { DetachedPromise } from '../../lib/detached-promise'\nimport {\n  scheduleImmediate,\n  atLeastOneTask,\n  waitAtLeastOneReactRenderTask,\n} from '../../lib/scheduler'\nimport { ENCODED_TAGS } from './encoded-tags'\nimport {\n  indexOfUint8Array,\n  isEquivalentUint8Arrays,\n  removeFromUint8Array,\n} from './uint8array-helpers'\nimport { MISSING_ROOT_TAGS_ERROR } from '../../shared/lib/errors/constants'\nimport {\n  RSC_HEADER,\n  NEXT_ROUTER_PREFETCH_HEADER,\n  NEXT_ROUTER_SEGMENT_PREFETCH_HEADER,\n  NEXT_RSC_UNION_QUERY,\n} from '../../client/components/app-router-headers'\nimport { computeCacheBustingSearchParam } from '../../shared/lib/router/utils/cache-busting-search-param'\nimport type { AnyStream } from '../app-render/stream-ops'\n\nfunction voidCatch() {\n  // this catcher is designed to be used with pipeTo where we expect the underlying\n  // pipe implementation to forward errors but we don't want the pipeTo promise to reject\n  // and be unhandled\n}\n\n// We can share the same encoder instance everywhere\n// Notably we cannot do the same for TextDecoder because it is stateful\n// when handling streaming data\nconst encoder = new TextEncoder()\n\nexport function chainStreams<T>(\n  ...streams: ReadableStream<T>[]\n): ReadableStream<T> {\n  // If we have no streams, return an empty stream. This behavior is\n  // intentional as we're now providing the `RenderResult.EMPTY` value.\n  if (streams.length === 0) {\n    return new ReadableStream<T>({\n      start(controller) {\n        controller.close()\n      },\n    })\n  }\n\n  // If we only have 1 stream we fast path it by returning just this stream\n  if (streams.length === 1) {\n    return streams[0]\n  }\n\n  const { readable, writable } = new TransformStream()\n\n  // We always initiate pipeTo immediately. We know we have at least 2 streams\n  // so we need to avoid closing the writable when this one finishes.\n  let promise = streams[0].pipeTo(writable, { preventClose: true })\n\n  let i = 1\n  for (; i < streams.length - 1; i++) {\n    const nextStream = streams[i]\n    promise = promise.then(() =>\n      nextStream.pipeTo(writable, { preventClose: true })\n    )\n  }\n\n  // We can omit the length check because we halted before the last stream and there\n  // is at least two streams so the lastStream here will always be defined\n  const lastStream = streams[i]\n  promise = promise.then(() => lastStream.pipeTo(writable))\n\n  // Catch any errors from the streams and ignore them, they will be handled\n  // by whatever is consuming the readable stream.\n  promise.catch(voidCatch)\n\n  return readable\n}\n\nexport function streamFromString(str: string): ReadableStream<Uint8Array> {\n  return new ReadableStream({\n    start(controller) {\n      controller.enqueue(encoder.encode(str))\n      controller.close()\n    },\n  })\n}\n\nexport function streamFromBuffer(chunk: Buffer): ReadableStream<Uint8Array> {\n  return new ReadableStream({\n    start(controller) {\n      controller.enqueue(chunk)\n      controller.close()\n    },\n  })\n}\n\nasync function streamToChunks(\n  stream: ReadableStream<Uint8Array>\n): Promise<Array<Uint8Array>> {\n  const reader = stream.getReader()\n  const chunks: Array<Uint8Array> = []\n\n  while (true) {\n    const { done, value } = await reader.read()\n    if (done) {\n      break\n    }\n\n    chunks.push(value)\n  }\n\n  return chunks\n}\n\nfunction concatUint8Arrays(chunks: Array<Uint8Array>): Uint8Array {\n  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0)\n  const result = new Uint8Array(totalLength)\n  let offset = 0\n  for (const chunk of chunks) {\n    result.set(chunk, offset)\n    offset += chunk.length\n  }\n  return result\n}\n\nexport async function webstreamToUint8Array(\n  stream: ReadableStream<Uint8Array>\n): Promise<Uint8Array> {\n  return concatUint8Arrays(await streamToChunks(stream))\n}\n\nfunction webToReadable(\n  stream: ReadableStream<Uint8Array> | import('node:stream').Readable\n): import('node:stream').Readable {\n  if (process.env.NEXT_RUNTIME === 'edge') {\n    throw new Error('webToReadable cannot be used in the edge runtime')\n  } else {\n    let Readable: typeof import('node:stream').Readable\n    if (process.env.TURBOPACK) {\n      Readable = (require('node:stream') as typeof import('node:stream'))\n        .Readable\n    } else if (\n      process.env.__NEXT_BUNDLER === 'Webpack' ||\n      process.env.__NEXT_BUNDLER === 'Rspack'\n    ) {\n      Readable = (\n        __non_webpack_require__('node:stream') as typeof import('node:stream')\n      ).Readable\n    } else {\n      Readable = (require('node:stream') as typeof import('node:stream'))\n        .Readable\n    }\n    if (stream instanceof Readable) {\n      return stream\n    }\n    return Readable.fromWeb(stream as import('stream/web').ReadableStream)\n  }\n}\n\nexport async function nodestreamToUint8Array(\n  stream: AnyStream\n): Promise<Uint8Array> {\n  const chunks: Buffer[] = []\n  for await (const chunk of webToReadable(stream)) {\n    chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk)\n  }\n  return Buffer.concat(chunks)\n}\n\nexport async function streamToUint8Array(stream: AnyStream) {\n  if (process.env.NEXT_RUNTIME === 'edge') {\n    // Edge runtime always uses web streams\n    return webstreamToUint8Array(stream as ReadableStream<Uint8Array>)\n  } else {\n    let Readable: typeof import('node:stream').Readable\n    if (process.env.TURBOPACK) {\n      Readable = (require('node:stream') as typeof import('node:stream'))\n        .Readable\n    } else if (\n      process.env.__NEXT_BUNDLER === 'Webpack' ||\n      process.env.__NEXT_BUNDLER === 'Rspack'\n    ) {\n      Readable = (\n        __non_webpack_require__('node:stream') as typeof import('node:stream')\n      ).Readable\